 for d in draft['profiles']:
  row=next(x for x in rows if x['entry_id']==d['entry_id']);assert row['status']=='untranslated' and not row['translation_ko'];text='\n'.join(d['draft_lines']);scene='Observed native credits root18=7/19=1/07DF1/06DE0 controlled scene,9417 mode5/6, producerA457 NMI124, scrollingFC/FF';row.update(translation_ko=text,status='draft',scene=scene,speaker='Credits',notes='Source observed2D/2E1001 and2F2361. Shared201/202 cloned original124 ASCII; staff names/KONAMI/legal rows binary and bitmap retained; FD32/literal00/output timing preserved. Controlled scene, not fullplay/game clear; final review pending.');preserved=[i for i,(old,new) in enumerate(zip(d['source_lines'],d['draft_lines'])) if new.ljust(len(old))==old];profiles.append({k:d[k] for k in ('entry_id','slot','source_file_offset','end_exclusive','source_raw_sha256','source_lines')}|{'slots':[d['slot']],'pointer':d['source_file_offset']+0x3ff0,'text':text,'font_bank':201,'NT':0x2005 if d['slot']==46 else 0x2805,'native_mode':6 if d['slot']==46 else 5,'preserved_lines':preserved,'scene':scene})
 buf=io.StringIO(newline='');w=csv.DictWriter(buf,fieldnames=list(rows[0]),lineterminator='\n');w.writeheader();w.writerows(rows);after=buf.getvalue().encode('utf-8-sig');assert len(rows)==54 and sum(x['status']=='draft' for x in rows)==45;backup.write_bytes(before);path.write_bytes(after);plan={'date':'2026-10-05','source_sha256':draft['source_ROM_sha256'],'prior_build':'dialogue_kr_poc_036','prior_ROM_sha256':draft['prior_ROM_sha256'],'backup_CSV_sha256':sha(before),'CSV_sha256':sha(after),'profiles':profiles,'native_font':124,'new_shared_font':[201,202],'producer_expected':{'file_offsets':[0x6468,0x26468],'expected_hex':'7c','final_hex':'c9'},'scope':'Work37 three actual credits drafts; all42 previous drafts retained; native names/publisher/legal kept','review':'Draft, recorded scene seed; no release'};planpath.write_text(json.dumps(plan,ensure_ascii=False,indent=2)+'\n',encoding='utf-8');print(json.dumps({'draft':45,'untranslated':9,'CSV_sha256':sha(after),'preserved_name_legal_rows':[p['preserved_lines'] for p in profiles]},indent=2))
